import "./home.css";

const HomePage = () => {
  return <section className="nav-bar">
    <nav className="nav-bar-links">
        <div className="nav-bar-links-menu-left">
            <a href="#">Home</a>
            <a href="#">About Us</a>
            <a href="#">Store</a>
        </div>
        <div className="nav-bar-links-menu-right">
            <a href="#">Cart</a>
            <a href="#">Profile</a>
        </div>
    </nav>
  </section>;
};

export default HomePage;
